.ssa-nav__list a{display:flex;align-items:center;min-height:44px;padding:.55rem .8rem;}
.ssa-nav__list a[aria-current="page"]{background:var(--ssa-accent);font-weight:700;text-decoration:underline;}

.ssa-header{padding:4rem 0 2.5rem;border-bottom:1px solid var(--ssa-border);}
.ssa-main{padding:3rem 0 5rem;}
.ssa-section{padding:2.5rem 0;border-bottom:1px solid var(--ssa-border);}
.ssa-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1.25rem;}
.ssa-card{padding:1.5rem;border:1px solid var(--ssa-border);border-radius:var(--ssa-radius);background:var(--ssa-surface);}
.ssa-definition{padding:1.5rem;border-left:4px solid var(--ssa-accent);background:#f8efd9;}
.ssa-index{list-style:none;padding:0;margin:0;}
.ssa-index li{border-bottom:1px solid var(--ssa-border);}
.ssa-index a{display:flex;justify-content:space-between;padding:1rem 0;}
.ssa-button-group{display:flex;flex-wrap:wrap;gap:.75rem;}
.ssa-button{display:inline-flex;align-items:center;min-height:44px;padding:.7rem 1rem;border:1px solid var(--ssa-border-strong);}
.ssa-button--primary{background:var(--ssa-accent);}

/* SSA reusable accessibility bar */

.ssa-accessibility {
  position: relative;
  z-index: 999;
  font-family: Arial, Helvetica, sans-serif;
}

.ssa-accessibility__toggle {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  min-height: 44px;
  padding: .65rem .9rem;
  border: 2px solid var(--ssa-border-strong, #a9895f);
  border-radius: var(--ssa-radius, 8px);
  background: var(--ssa-surface, #fff);
  color: var(--ssa-text, #30261e);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.ssa-accessibility__panel {
  border-top: 1px solid var(--ssa-border, #dac5a3);
  border-bottom: 1px solid var(--ssa-border, #dac5a3);
  background: var(--ssa-surface, #fff);
  color: var(--ssa-text, #30261e);
}

