  width: min(calc(100% - 2rem), var(--ssa-max-width, 1180px));
  margin-inline: auto;
  padding: 1.25rem 0;
}

.ssa-accessibility__heading-row {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 1rem;
}

.ssa-accessibility__heading-row h2 {
  margin: 0;
  font-size: 1.35rem;
}

.ssa-accessibility__close {
  min-width: 44px;
  min-height: 44px;
