(function () {
  "use strict";

  var STORAGE_KEY = "ssaAccessibilitySettings";
  var root = document.documentElement;
  var bar = document.querySelector("[data-ssa-accessibility]");

  if (!bar) return;

  var toggle = bar.querySelector(".ssa-accessibility__toggle");
  var panel = bar.querySelector(".ssa-accessibility__panel");
  var closeButton = bar.querySelector(".ssa-accessibility__close");
  var status = bar.querySelector(".ssa-accessibility__status");
  var controls = bar.querySelectorAll("[data-ssa-action]");

  var defaults = {
    textSize: 0,
    dyslexia: false,
    contrast: false,
    soft: false,
    spacing: false,
    motion: false
  };

  function loadSettings() {
    try {
      return Object.assign({}, defaults, JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}"));
    } catch (error) {
      return Object.assign({}, defaults);
    }
  }

  var settings = loadSettings();

  function saveSettings() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
    } catch (error) {
      /* Settings still work for the current page if storage is unavailable. */
    }
  }

  function announce(message) {
    status.textContent = "";
    window.setTimeout(function () {
      status.textContent = message;
    }, 20);
  }

  function setPressed(action, pressed) {
    var button = bar.querySelector('[data-ssa-action="' + action + '"]');
    if (button && action !== "reset" && action !== "text-increase" && action !== "text-decrease") {
      button.setAttribute("aria-pressed", String(pressed));
    }
  }

  function applySettings() {
    root.classList.toggle("ssa-text-large", settings.textSize === 1);
    root.classList.toggle("ssa-text-larger", settings.textSize === 2);
    root.classList.toggle("ssa-dyslexia-friendly", settings.dyslexia);
    root.classList.toggle("ssa-high-contrast", settings.contrast);
    root.classList.toggle("ssa-soft-colours", settings.soft && !settings.contrast);
    root.classList.toggle("ssa-more-spacing", settings.spacing);
    root.classList.toggle("ssa-reduce-motion", settings.motion);

    setPressed("dyslexia", settings.dyslexia);
    setPressed("contrast", settings.contrast);
    setPressed("soft", settings.soft);
    setPressed("spacing", settings.spacing);
    setPressed("motion", settings.motion);

    saveSettings();
  }

  function openPanel() {
    panel.hidden = false;
    toggle.setAttribute("aria-expanded", "true");
  }

  function closePanel() {
    panel.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
    toggle.focus();
  }

  toggle.addEventListener("click", function () {
    if (panel.hidden) {
      openPanel();
    } else {
      closePanel();
    }
  });

  closeButton.addEventListener("click", closePanel);

  bar.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !panel.hidden) {
      closePanel();
    }
  });

  controls.forEach(function (button) {
    button.addEventListener("click", function () {
      var action = button.getAttribute("data-ssa-action");

      if (action === "text-increase") {
        settings.textSize = Math.min(2, settings.textSize + 1);
        announce(settings.textSize === 2 ? "Text is at the largest size." : "Text size increased.");
      }

      if (action === "text-decrease") {
        settings.textSize = Math.max(0, settings.textSize - 1);
        announce(settings.textSize === 0 ? "Text is at the default size." : "Text size decreased.");
      }

      if (action === "dyslexia") {
        settings.dyslexia = !settings.dyslexia;
        announce("Dyslexia-friendly font " + (settings.dyslexia ? "on." : "off."));
      }

      if (action === "contrast") {
        settings.contrast = !settings.contrast;
        if (settings.contrast) settings.soft = false;
        announce("High contrast " + (settings.contrast ? "on." : "off."));
      }

      if (action === "soft") {
        settings.soft = !settings.soft;
        if (settings.soft) settings.contrast = false;
        announce("Softer colours " + (settings.soft ? "on." : "off."));
      }

      if (action === "spacing") {
        settings.spacing = !settings.spacing;
        announce("Extra spacing " + (settings.spacing ? "on." : "off."));
      }

      if (action === "motion") {
        settings.motion = !settings.motion;
        announce("Reduced motion " + (settings.motion ? "on." : "off."));
      }

      if (action === "reset") {
        settings = Object.assign({}, defaults);
        announce("Accessibility settings reset.");
      }

      applySettings();
    });
