  --ssa-muted: #fff;
  --ssa-border: #fff;
  --ssa-border-strong: #fff;
  --ssa-accent: #ffea00;
  --ssa-focus: #00ffff;
}

html.ssa-soft-colours {
  --ssa-background: #f3efe5;
  --ssa-surface: #faf7ef;
  --ssa-text: #2f2b26;
  --ssa-text-secondary: #413b34;
