    }
  }

  function applySettings() {
    root.classList.toggle("ssa-text-large", settings.textSize === 1);
    root.classList.toggle("ssa-text-larger", settings.textSize === 2);
    root.classList.toggle("ssa-dyslexia-friendly", settings.dyslexia);
    root.classList.toggle("ssa-high-contrast", settings.contrast);
    root.classList.toggle("ssa-soft-colours", settings.soft && !settings.contrast);
    root.classList.toggle("ssa-more-spacing", settings.spacing);
    root.classList.toggle("ssa-reduce-motion", settings.motion);

    setPressed("dyslexia", settings.dyslexia);
    setPressed("contrast", settings.contrast);
    setPressed("soft", settings.soft);
    setPressed("spacing", settings.spacing);
    setPressed("motion", settings.motion);

