        settings.contrast = !settings.contrast;
        if (settings.contrast) settings.soft = false;
        announce("High contrast " + (settings.contrast ? "on." : "off."));
      }

      if (action === "soft") {
        settings.soft = !settings.soft;
        if (settings.soft) settings.contrast = false;
        announce("Softer colours " + (settings.soft ? "on." : "off."));
      }

      if (action === "spacing") {
        settings.spacing = !settings.spacing;
        announce("Extra spacing " + (settings.spacing ? "on." : "off."));
      }

      if (action === "motion") {
        settings.motion = !settings.motion;
        announce("Reduced motion " + (settings.motion ? "on." : "off."));
      }

