*::after{box-sizing:border-box;}

html{scroll-behavior:smooth;}

.ssa-page{
  margin:0;
  background:var(--ssa-background);
  color:var(--ssa-text);
  font:17px/1.7 Arial,Helvetica,sans-serif;
}

.ssa-container{
  width:min(calc(100% - 2rem),var(--ssa-max-width));
  margin-inline:auto;
}

.ssa-reading-width{max-width:var(--ssa-reading-width);}

.ssa-skip-link{position:absolute;left:1rem;top:0;transform:translateY(-150%);}
.ssa-skip-link:focus{transform:translateY(0);}

.ssa-nav{border-bottom:1px solid var(--ssa-border);}
.ssa-nav__inner{display:flex;justify-content:space-between;align-items:center;padding:.85rem 0;gap:1rem;}
.ssa-nav__list{display:flex;flex-wrap:wrap;gap:.25rem;list-style:none;margin:0;padding:0;}
.ssa-nav__list a{display:flex;align-items:center;min-height:44px;padding:.55rem .8rem;}
.ssa-nav__list a[aria-current="page"]{background:var(--ssa-accent);font-weight:700;text-decoration:underline;}

.ssa-header{padding:4rem 0 2.5rem;border-bottom:1px solid var(--ssa-border);}
.ssa-main{padding:3rem 0 5rem;}
.ssa-section{padding:2.5rem 0;border-bottom:1px solid var(--ssa-border);}
.ssa-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1.25rem;}
.ssa-card{padding:1.5rem;border:1px solid var(--ssa-border);border-radius:var(--ssa-radius);background:var(--ssa-surface);}
.ssa-definition{padding:1.5rem;border-left:4px solid var(--ssa-accent);background:#f8efd9;}
.ssa-index{list-style:none;padding:0;margin:0;}
.ssa-index li{border-bottom:1px solid var(--ssa-border);}
.ssa-index a{display:flex;justify-content:space-between;padding:1rem 0;}
.ssa-button-group{display:flex;flex-wrap:wrap;gap:.75rem;}
.ssa-button{display:inline-flex;align-items:center;min-height:44px;padding:.7rem 1rem;border:1px solid var(--ssa-border-strong);}
.ssa-button--primary{background:var(--ssa-accent);}

/* SSA reusable accessibility bar */

.ssa-accessibility {
  position: relative;
  z-index: 999;
  font-family: Arial, Helvetica, sans-serif;
}

.ssa-accessibility__toggle {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  min-height: 44px;
  padding: .65rem .9rem;
  border: 2px solid var(--ssa-border-strong, #a9895f);
  border-radius: var(--ssa-radius, 8px);
  background: var(--ssa-surface, #fff);
  color: var(--ssa-text, #30261e);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.ssa-accessibility__panel {
  border-top: 1px solid var(--ssa-border, #dac5a3);
  border-bottom: 1px solid var(--ssa-border, #dac5a3);
  background: var(--ssa-surface, #fff);
  color: var(--ssa-text, #30261e);
}

.ssa-accessibility__panel-inner {
  width: min(calc(100% - 2rem), var(--ssa-max-width, 1180px));
  margin-inline: auto;
  padding: 1.25rem 0;
}

.ssa-accessibility__heading-row {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 1rem;
}

.ssa-accessibility__heading-row h2 {
  margin: 0;
  font-size: 1.35rem;
}

.ssa-accessibility__close {
  min-width: 44px;
  min-height: 44px;
  border: 1px solid var(--ssa-border-strong, #a9895f);
  border-radius: var(--ssa-radius, 8px);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 1.5rem;
  cursor: pointer;
}

.ssa-accessibility__links,
.ssa-accessibility__controls {
  display: flex;
  flex-wrap: wrap;
  gap: .65rem;
  margin-top: 1rem;
}

.ssa-accessibility__links a,
.ssa-accessibility__controls button {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: .65rem .85rem;
  border: 1px solid var(--ssa-border-strong, #a9895f);
  border-radius: var(--ssa-radius, 8px);
  background: var(--ssa-background, #fdf8f3);
  color: var(--ssa-text, #30261e);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: .2em;
}

.ssa-accessibility__controls button[aria-pressed="true"] {
  border-width: 3px;
  background: var(--ssa-accent, #dea93f);
}

.ssa-accessibility__status {
  min-height: 1.5em;
  margin: 1rem 0 0;
  font-weight: 700;
}

/* User-selected page states */

html.ssa-text-large {
  font-size: 112.5%;
}

html.ssa-text-larger {
  font-size: 125%;
}

html.ssa-dyslexia-friendly body,
html.ssa-dyslexia-friendly .ssa-page {
  font-family: Verdana, Arial, sans-serif !important;
}

html.ssa-high-contrast {
  --ssa-background: #000;
  --ssa-surface: #000;
  --ssa-text: #fff;
  --ssa-text-secondary: #fff;
  --ssa-muted: #fff;
  --ssa-border: #fff;
  --ssa-border-strong: #fff;
  --ssa-accent: #ffea00;
  --ssa-focus: #00ffff;
}

html.ssa-soft-colours {
  --ssa-background: #f3efe5;
  --ssa-surface: #faf7ef;
  --ssa-text: #2f2b26;
  --ssa-text-secondary: #413b34;
  --ssa-border: #c8bda8;
  --ssa-border-strong: #8c806d;
  --ssa-accent: #c99535;
}

html.ssa-more-spacing body,
html.ssa-more-spacing .ssa-page {
  line-height: 2 !important;
  letter-spacing: .04em;
  word-spacing: .12em;
}

html.ssa-more-spacing p,
html.ssa-more-spacing li {
  margin-bottom: 1.25em;
}

html.ssa-reduce-motion *,
html.ssa-reduce-motion *::before,
html.ssa-reduce-motion *::after {
  scroll-behavior: auto !important;
  animation-duration: .01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: .01ms !important;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

@media (max-width: 700px) {
  .ssa-accessibility__links,
  .ssa-accessibility__controls {
    display: grid;
    grid-template-columns: 1fr;
  }

  .ssa-accessibility__links a,
  .ssa-accessibility__controls button {
    width: 100%;
  }
}

.ssa-machine-meta{margin:1.5rem 0;padding:1.25rem;border:1px solid var(--ssa-border,#dac5a3);border-radius:var(--ssa-radius,8px);background:var(--ssa-surface,#fff)}
.ssa-machine-meta h2{margin-top:0;font-size:1.2rem}.ssa-machine-meta dl{display:grid;grid-template-columns:minmax(10rem,14rem) 1fr;gap:.45rem 1rem;margin:0}.ssa-machine-meta dt{font-weight:700}.ssa-machine-meta dd{margin:0;overflow-wrap:anywhere}.ssa-machine-meta code{white-space:normal}.ssa-semantic-principles{padding:1rem 1.25rem;border-left:4px solid var(--ssa-accent,#dea93f);background:var(--ssa-background,#fdf8f3)}
@media(max-width:650px){.ssa-machine-meta dl{grid-template-columns:1fr}.ssa-machine-meta dd{margin-bottom:.7rem}}

