:root {
  --ssa-background:#fdf8f3;
  --ssa-surface:#ffffff;
  --ssa-text:#30261e;
  --ssa-text-secondary:#483526;
  --ssa-muted:#6d5435;
  --ssa-border:#dac5a3;
  --ssa-border-strong:#a9895f;
  --ssa-accent:#dea93f;
  --ssa-focus:#1f5f78;
  --ssa-max-width:1180px;
